classdef NMCVPartitionTools
% NMCVPartitionTools
% -------------------------------------------------------------------------
% Browser-UI port of the legacy nk_CVpartition_config.m branch.  This class
% keeps the backend contract unchanged: browser-only fields are stored in the
% menu state, while NM.TrainParam.RAND and NM.cv retain the legacy layout.
% CV structures are generated by the legacy nk_MakeCrossFolds function.
% -------------------------------------------------------------------------

    properties (Constant, Access = private)
        FrameworkChoices = struct( ...
            'symbol', {'pooled','outer_group_inner_pooled','nested_group','outer_group_inner_group_in'}, ...
            'code', {1,2,3,4}, ...
            'description', {'Pooled cross-validation','Outer Leave-Group-Out / Inner pooled', ...
                            'Nested Leave-Group-Out','Outer Leave-Group-Out / Inner Leave-Group-In'})
        DecompositionChoices = struct( ...
            'symbol', {'one_vs_one','one_vs_all','none'}, 'code', {1,2,9}, ...
            'description', {'Binary one-vs-one decomposition', ...
                            'Binary one-vs-rest decomposition', ...
                            'No decomposition, for true multiclass learners'})
        ModeChoices = struct( ...
            'symbol', {'kfold','loo','group'}, 'code', {'kfold','loo','group'}, ...
            'description', {'Repeated K-fold cross-validation', ...
                            'Leave-one-out cross-validation', ...
                            'Group-based cross-validation'})
    end

    methods (Static)

        function [NM, state, report] = cli_configure(NM, varargin)
            % cli_configure  Programmatically configure cross-validation partition settings.
            %
            % Merges optional state/name-value inputs into stateFromNM, accepts only the canonical state keys, normalizes CV2/CV1/equalization fields, writes NM.TrainParam.RAND/NM.cv via applyToNM, and returns a report. This is the API-facing counterpart of the browser CV partition page.
            if nargin < 1 || isempty(NM), NM = struct(); end
            if exist('NMStatusGuardTools','class') == 8
                NMStatusGuardTools.assertTrainingConfigurationMode(NM, 'NMCVPartitionTools.configure');
            end
            defaultState = NMCVPartitionTools.stateFromNM(NM);
            [state, ~, report] = NMConfigureAPITools.parseState(defaultState, varargin, {}, true);
            if ~report.ok, return; end
            try
                state = NMCVPartitionTools.cliNormalizeFriendlyValues(state);
                state = NMCVPartitionTools.normalizeState(NM, state);
                NM = NMCVPartitionTools.applyToNM(NM, state);
                if isempty(report.message), report.message = 'Cross-validation configuration applied.'; end
            catch ME
                report = NMConfigureAPITools.appendException(report, ME);
            end
        end

        function [NM, state, report] = configure(NM, varargin)
            % configure  Configure NeuroMiner cross-validation through the public API.
            %
            %   [NM, state, report] = NMCVPartitionTools.configure(NM, name, value, ...)
            %   writes the legacy NM.TrainParam.RAND branch, and optionally
            %   NM.cv, through the centralized CV-partition port. Use this API
            %   instead of editing NM.TrainParam.RAND or NM.cv directly.
            %
            %   Common name/value options are:
            %       cvFramework        CV framework. Friendly values include
            %                        'pooled', 'outer_group_inner_pooled',
            %                        'nested_group' or numeric legacy codes.
            %       cvOuterMode          Outer-CV mode: 'kfold', 'loo' or 'group'.
            %       cvOuterFold         Outer-CV folds, or -1 for leave-one-out.
            %       cvOuterPerm         Number of outer-CV permutations.
            %       cvInnerMode          Inner-CV mode: 'kfold', 'loo' or 'group'.
            %       cvInnerFold         Inner-CV folds, or -1 for leave-one-out.
            %       cvInnerPerm         Number of inner-CV permutations.
            %       cvOuterGroupIndex    Subject-level group index for outer CV.
            %       cvInnerGroupIndex    Subject-level group index for inner CV.
            %       cvConstrainedGroupIndex Subject-level index for constrained CV.
            %       cvDecompose        'one_vs_one', 'one_vs_all', 'none' or
            %                        numeric legacy values.
            %       cvBuildRequested          Logical. If false, only RAND is written;
            %                        if true, NM.cv is built via the legacy
            %                        fold-generation backend.
            %       LoadCV/SaveCV    Logical flags with LoadPath/SavePath.
            %
            %   state is the normalized CV configuration. report.ok indicates
            %   whether parsing/normalization/application succeeded.
            %
            %   Example:
            %       [NM, cvState, rep] = NMCVPartitionTools.configure(NM, ...
            %           'cvOuterFold',2,'cvOuterPerm',1,'cvInnerFold',2, ...
            %           'cvInnerPerm',1,'cvBuildRequested',true);
            %
            %   See also NMCVPartitionTools.configureHelp.

            [NM, state, report] = NMCVPartitionTools.cli_configure(NM, varargin{:});
        end

        function h = cli_configureHelp()
            % cli_configureHelp  Describe the scripted CV partition configuration interface.
            %
            % Returns option metadata and examples for cli_configure, including CV framework, inner/outer folds, grouped/constrained CV and equalization controls. The method is read-only and supports documentation and scaffold generation.
            opts = struct();
            opts.cvOuterFold = 'Outer CV2 folds; positive integer, or -1 for leave-one-out.';
            opts.cvOuterPerm = 'Outer CV2 permutations; positive integer.';
            opts.cvInnerFold = 'Inner CV1 folds; positive integer, or -1 for leave-one-out.';
            opts.cvInnerPerm = 'Inner CV1 permutations; positive integer.';
            opts.cvConstrainedGroupIndex = 'Subject-level grouping vector for constrained CV.';
            opts.cvBuildRequested = 'false writes NM.TrainParam.RAND only; true also builds NM.cv through the legacy backend.';
            h = NMConfigureAPITools.helpStruct('NMCVPartitionTools.cli_configure', ...
                '[NM, state, report] = NMCVPartitionTools.cli_configure(NM, existingState, name, value, ...)', opts, ...
                {'[NM, cvState] = NMCVPartitionTools.cli_configure(NM, ''cvOuterFold'', 10, ''cvOuterPerm'', 5, ''cvInnerFold'', 10, ''cvBuildRequested'', false);'}, NMCVPartitionTools.apiChoices());
            h.validationRules = {'Decompose applies to multiclass classification; binary/regression defaults to one_vs_one.'; ...
                'Multiclass leave-one-out CV forces one_vs_all decomposition.'; ...
                'Grouped CV frameworks enforce group-based outer CV and, where applicable, inner CV.'};
        end

        function choices = apiChoices()
            choices.cvFramework = NMCVPartitionTools.FrameworkChoices;
            choices.cvDecompose = NMCVPartitionTools.DecompositionChoices;
            choices.cvOuterMode = NMCVPartitionTools.ModeChoices;
            choices.cvInnerMode = choices.cvOuterMode;
        end

        function h = configureHelp()
            % configureHelp  Return browser/API help metadata for the CV partition branch.
            %
            % Provides a compact help struct used by configuration surfaces that need the available CV fields without invoking legacy menus or changing NM.
            h = NMCVPartitionTools.cli_configureHelp();
        end

        function state = stateFromNM(NM)
            % stateFromNM  Reconstruct browser CV state from NM.TrainParam.RAND and NM.cv.
            %
            % Reads the legacy cross-validation fields, applies modular defaults, derives current fold/permutation counts where possible, and returns a fixed state struct. The method is read-only and is the starting point for both browser editing and scripted updates.
            RAND = NMCVPartitionTools.defaultRAND(NM);
            if isfield(NM,'TrainParam') && isstruct(NM.TrainParam) && ...
                    isfield(NM.TrainParam,'RAND') && isstruct(NM.TrainParam.RAND)
                RAND = NMCVPartitionTools.mergeStruct(RAND, NM.TrainParam.RAND);
            end
            RAND = NMCVPartitionTools.completeRAND(NM, RAND);

            state = struct();
            state.cvFramework = double(RAND.CV2Frame);
            state.cvOuterMode = NMCVPartitionTools.outerModeFromRAND(NM, RAND);
            state.cvInnerMode = NMCVPartitionTools.innerModeFromRAND(NM, RAND);
            state.cvOuterPerm = double(RAND.OuterPerm);
            state.cvOuterFold = double(RAND.OuterFold);
            state.cvInnerPerm = double(RAND.InnerPerm);
            state.cvInnerFold = double(RAND.InnerFold);
            state.cvDecompose = double(RAND.Decompose);
            [state.cvIsMulticlass, ~, ~] = NMAlternativeLabelTools.effectiveClassInfo(NM);
            state.cvHasStructure = isfield(NM,'cv') && ~isempty(NM.cv);
            state.cvCanSave = state.cvHasStructure;
            state.cvCanAppend = NMCVPartitionTools.canAppend(NM, RAND);
            state.cvAppendMode = 0;
            state.cvBuildRequested = false;
            state.cvLoadRequested = false;
            state.cvLoadPath = '';
            state.cvSaveRequested = false;
            state.cvSavePath = '';

            state.cvOuterGroupSourceVar = '';
            state.cvInnerGroupSourceVar = '';
            state.cvConstrainedSourceVar = '';
            state.cvOnlyGroupSourceVar = '';
            state.cvEqCovariateIndex = 0;
            state.cvEqTarget = 'label';

            state.cvOuterGroupIndex = [];
            state.cvInnerGroupIndex = [];
            if isfield(RAND,'CV2LCO') && isstruct(RAND.CV2LCO) && isfield(RAND.CV2LCO,'ind')
                state.cvOuterGroupIndex = RAND.CV2LCO.ind(:);
            end
            if isfield(RAND,'CV1LCO') && isstruct(RAND.CV1LCO) && isfield(RAND.CV1LCO,'ind')
                state.cvInnerGroupIndex = RAND.CV1LCO.ind(:);
            end
            state.cvOuterGroupSummary = NMCVPartitionTools.indexSummary(state.cvOuterGroupIndex);
            state.cvInnerGroupSummary = NMCVPartitionTools.indexSummary(state.cvInnerGroupIndex);

            state.cvEqEnabled = logical(RAND.Eq.enabled);
            state.cvEqAddRemoved2Test = logical(RAND.Eq.addremoved2test);
            state.cvEqMinCount = double(RAND.Eq.mincount);
            state.cvEqMaxCount = double(RAND.Eq.maxcount);
            state.cvEqBinCount = double(RAND.Eq.bincount);
            state.cvEqPosNegRatio = double(RAND.Eq.posnegrat);
            state.cvEqCovar = RAND.Eq.Covar;
            state.cvEqCovarName = char(string(NMCVPartitionTools.getField(RAND.Eq,'CovarName','NM.label')));
            if ~strcmp(state.cvEqCovarName,'NM.label')
                state.cvEqTarget = 'covariate';
                if isfield(NM,'covnames') && ~isempty(NM.covnames)
                    ix = find(strcmp(cellstr(string(NM.covnames)), state.cvEqCovarName), 1);
                    if ~isempty(ix), state.cvEqCovariateIndex = ix; end
                end
            end

            state.cvConstrainedCV = double(RAND.ConstrainedCV);
            state.cvConstrainedGroupIndex = RAND.ConstrainedGroupIndex(:);
            state.cvConstrainedGroupSummary = NMCVPartitionTools.indexSummary(state.cvConstrainedGroupIndex);

            state.cvOnlyGroupFlag = double(RAND.CVOnlyGroup.flag);
            state.cvOnlyGroupIndex = RAND.CVOnlyGroup.index(:);
            state.cvOnlyGroupLevel = double(RAND.CVOnlyGroup.level);
            state.cvOnlyGroupSummary = NMCVPartitionTools.indexSummary(state.cvOnlyGroupIndex);

            state.cvModeFlag = NMAlternativeLabelTools.effectiveMode(NM);
            state.cvNSamples = NMCVPartitionTools.nSamples(NM);
            state.cvCovariateNames = NMCVPartitionTools.covariateNames(NM);
            state.cvVectorCandidates = {};
        end


        function RAND = defaultSetting(NM)
            % defaultSetting  Public legacy default for nk_CVpartition_config/RAND.
            if nargin < 1 || isempty(NM), NM = struct(); end
            RAND = NMCVPartitionTools.completeRAND(NM, NMCVPartitionTools.defaultRAND(NM));
        end

        function source = importedGroupSource(NM, index)
            % Express an observed grouping vector by the imported covariate that owns it.
            source = '';
            matches = 0;
            for k = 1:numel(NM.covnames)
                if isequaln(index(:),NM.covars(:,k))
                    matches = matches + 1;
                    source = ['NM.covars:' char(NM.covnames{k})];
                end
            end
            assert(matches==1,'NMCVPartitionTools:groupSource', ...
                'CV grouping must correspond to exactly one named imported NM covariate.');
        end

        function index = importedGroupColumn(NM, source)
            % Resolve one canonical imported-NM covariate selector for CV grouping.
            assert(startsWith(source,'NM.covars:'),'NMCVPartitionTools:groupSource', ...
                'Imported group selector must start with NM.covars:.');
            name = source(11:end);
            col = find(strcmp(NM.covnames,name));
            assert(isscalar(col),'NMCVPartitionTools:groupSource', ...
                'Grouping covariate %s must occur exactly once.',name);
            index = NM.covars(:,col);
        end

        function candidates = workspaceCandidates(workspaceCatalog)
            % workspaceCandidates  Filter workspace variables usable as grouped or constrained CV vectors.
            %
            % Uses metadata only to identify vectors with plausible subject-level length. Candidate values are not loaded here; stateFromMenu/applyToNM handle selected variables later in the configuration flow.
            candidates = NMWorkspaceTools.subjectVectorCandidates(workspaceCatalog);
        end

        function state = stateFromMenu(NM, currentState, menuState)
            % stateFromMenu  Translate browser CV menu state into a normalized configuration state.
            %
            % Combines the current state with UI selections for framework, folds, group variables, constrained CV and equalization. The method prepares state for applyToNM but does not directly modify NM.
            state = currentState;
            if isempty(state) || ~isstruct(state), state = NMCVPartitionTools.stateFromNM(NM); end
            if isfield(menuState,'cv') && isstruct(menuState.cv)
                incoming = menuState.cv;
            else
                incoming = NMCVPartitionTools.flatCVFields(menuState);
            end
            fields = fieldnames(incoming);
            for i = 1:numel(fields)
                state.(fields{i}) = incoming.(fields{i});
            end
            state = NMCVPartitionTools.normalizeState(NM, state);
        end

        function NM = applyToNM(NM, state)
            % applyToNM  Write normalized CV partition settings back into NM.
            %
            % Materializes the state into NM.TrainParam.RAND and invokes buildCV when fold structures must be generated. It is the only public writer in this class and preserves the legacy NM.cv contract expected by downstream preprocessing and training.
            %
            % state.cvAppendMode: carries the cv append mode value between browser/API state and legacy NeuroMiner structures.
            % state.cvBuildRequested: carries the cv build requested value between browser/API state and legacy NeuroMiner structures.
            % state.cvLoadPath: carries the cv load path value between browser/API state and legacy NeuroMiner structures.
            % state.cvLoadRequested: carries the cv load requested value between browser/API state and legacy NeuroMiner structures.
            % state.cvSavePath: carries the cv save path value between browser/API state and legacy NeuroMiner structures.
            % state.cvSaveRequested: carries the cv save requested value between browser/API state and legacy NeuroMiner structures.
            if isempty(state) || ~isstruct(state), return; end
            if ~isfield(NM,'TrainParam') || ~isstruct(NM.TrainParam), NM.TrainParam = struct(); end
            if ~isfield(NM.TrainParam,'RAND') || ~isstruct(NM.TrainParam.RAND)
                NM.TrainParam.RAND = NMCVPartitionTools.defaultRAND(NM);
            end
            state = NMCVPartitionTools.normalizeState(NM, state);
            RAND = NMCVPartitionTools.RANDFromState(NM, state);
            NM.TrainParam.RAND = RAND;

            if isfield(state,'cvLoadRequested') && logical(state.cvLoadRequested) && ...
                    isfield(state,'cvLoadPath') && ~isempty(state.cvLoadPath)
                NM = NMCVPartitionTools.loadCV(NM, state.cvLoadPath);
            end
            if isfield(state,'cvBuildRequested') && logical(state.cvBuildRequested)
                appendfl = 0;
                if isfield(state,'cvAppendMode') && ~isempty(state.cvAppendMode)
                    appendfl = round(double(state.cvAppendMode));
                end
                try
                    NM = NMCVPartitionTools.buildCV(NM, appendfl);
                catch ME
                    error('NMCVPartitionTools:buildFailed', ...
                        'Build Cross-Validation structure failed. NM.cv was not changed. Reason: %s', ME.message);
                end
            end
            if isfield(state,'cvSaveRequested') && logical(state.cvSaveRequested) && ...
                    isfield(state,'cvSavePath') && ~isempty(state.cvSavePath)
                NMCVPartitionTools.saveCV(NM, state.cvSavePath);
            end
        end

        function NM = buildCV(NM, appendfl)
            % buildCV  Generate or append legacy NM.cv fold structures from TrainParam.RAND.
            %
            % Delegates fold construction to nk_MakeCrossFolds when available and stores the resulting CV definition in NM.cv. appendfl controls whether generated folds replace or extend existing outer CV entries.
            if exist('nk_MakeCrossFolds','file') ~= 2
                error('NMCVPartitionTools:missingBuilder', ...
                    'nk_MakeCrossFolds.m is not available on the MATLAB path. Add the legacy CV builder before building NM.cv.');
            end
            if nargin < 2 || isempty(appendfl), appendfl = 0; end
            appendfl = round(double(appendfl));
            if ~isfinite(appendfl) || ~ismember(appendfl,0:3), appendfl = 0; end

            % Preserve the legacy CV contract: nk_MakeCrossFolds receives the
            % complete active label matrix once and returns one scalar CV structure.
            % Multi-label columns are target dimensions, not independent CV containers.
            groups = [];
            LABEL = NMAlternativeLabelTools.extractLabel(NM);
            if LABEL.flag == 1
                if isfield(LABEL,'newgroupnames'), groupnames = LABEL.newgroupnames; else, groupnames = []; end
            elseif isfield(NM,'groupnames')
                groupnames = NM.groupnames;
            else
                groupnames = [];
            end
            label = NMAlternativeLabelTools.activeLabel(NM);
            RAND = NM.TrainParam.RAND;
            modeflag = NMAlternativeLabelTools.effectiveMode(NM);

            if appendfl ~= 0 && ~NMCVPartitionTools.canAppend(NM, RAND)
                error('NMCVPartitionTools:appendUnavailable', ...
                    'The existing NM.cv is not compatible with the requested CV2/CV1 fold dimensions. Rebuild/overwrite instead.');
            end

            hasExistingCV = isfield(NM,'cv') && ~isempty(NM.cv);
            oldcv = [];
            if appendfl ~= 0 && hasExistingCV, oldcv = NM.cv; end

            cvOut = nk_MakeCrossFolds(label, RAND, modeflag, groups, groupnames, oldcv, appendfl);
            if isempty(cvOut)
                error('NMCVPartitionTools:emptyCV', ...
                    'nk_MakeCrossFolds returned an empty CV structure.');
            end
            if ~isstruct(cvOut) || ~isscalar(cvOut)
                error('NMCVPartitionTools:invalidCVShape', ...
                    'nk_MakeCrossFolds must return one scalar CV structure.');
            end

            if appendfl == 1 && hasExistingCV
                NM.cv = NMCVPartitionTools.appendOuterCV(oldcv, cvOut, modeflag);
            else
                NM.cv = cvOut;
            end
        end

        function NM = extendSubjects(NM, nExisting)
            % extendSubjects  Add new subject rows to existing pooled nested CV.
            %
            % NM already contains the appended labels. Original outer/inner
            % assignments remain unchanged; only the new subject rows are
            % partitioned through the inherited nk_CVpartition allocator.
            % This is distinct from cv append modes 1-3 (permutation/metadata).
            label = NMAlternativeLabelTools.activeLabel(NM);
            RAND = NMCVPartitionTools.completeRAND(NM, NM.TrainParam.RAND);
            modeflag = NMAlternativeLabelTools.effectiveMode(NM);
            classStratified = strcmp(modeflag,'classification') && RAND.Decompose ~= 9;
            nTotal = size(label,1);
            assert(isscalar(nExisting) && isfinite(nExisting) && nExisting == fix(nExisting) && ...
                nExisting > 0 && nExisting < nTotal && nTotal <= intmax('uint16'), ...
                'NMCVPartitionTools:subjectRange', ...
                'Subject extension requires appended rows and at most 65535 total subjects.');
            assert(size(label,2) == 1, 'NMCVPartitionTools:subjectLabels', ...
                'Subject extension requires one outcome column.');
            assert(all(isfinite(label(nExisting+1:end,:))), ...
                'NMCVPartitionTools:subjectLabels', ...
                'New subjects must have finite outcomes.');
            assert(RAND.CV2Frame == 1 && RAND.OuterFold > 1 && ...
                RAND.OuterFold < nExisting && RAND.InnerFold > 1 && ...
                RAND.ConstrainedCV ~= 1 && ~RAND.Eq.enabled && ...
                RAND.CVOnlyGroup.flag ~= 1, ...
                'NMCVPartitionTools:subjectFramework', ...
                'Incremental subjects require unconstrained pooled k-fold CV without equalization.');
            % nm2-allow: Legacy RAND CV2LCO is an optional grouped-CV branch.
            assert(~isfield(RAND,'CV2LCO') || isempty(RAND.CV2LCO), ...
                'NMCVPartitionTools:subjectFramework','Grouped CV2 cannot be incrementally extended.');
            % nm2-allow: Legacy RAND CV1LCO is an optional grouped-CV branch.
            assert(~isfield(RAND,'CV1LCO') || isempty(RAND.CV1LCO), ...
                'NMCVPartitionTools:subjectFramework','Grouped CV1 cannot be incrementally extended.');

            cv = NM.cv;
            [nPerm, nFold] = size(cv.TrainInd);
            assert(nFold == RAND.OuterFold, 'NMCVPartitionTools:subjectShape', ...
                'Existing CV2 fold count differs from RAND.');
            assert(isequal(size(cv.TestInd),[nPerm nFold]), ...
                'NMCVPartitionTools:subjectShape','Existing CV2 train/test dimensions differ.');
            assert(isequal(size(cv.cvin),[nPerm nFold]), ...
                'NMCVPartitionTools:subjectShape','Existing CV2/inner structures differ.');
            partitionLabels = label(nExisting+1:end);
            if ~classStratified
                partitionLabels = ones(size(partitionLabels));
            end
            newOuter = nk_CVpartition(nPerm, nFold, partitionLabels, [], [], false, ...
                'SilenceCVLog', true);

            for p = 1:nPerm
                oldTests = vertcat(cv.TestInd{p,:});
                assert(isequal(sort(double(oldTests(:))), (1:nExisting)'), ...
                    'NMCVPartitionTools:subjectCoverage', ...
                    'Existing CV2 test assignments do not cover the original cohort exactly once.');
                for f = 1:nFold
                    oldTrain = cv.TrainInd{p,f};
                    oldTrainN = numel(oldTrain);
                    % Rotate the inherited fold allocation across successive
                    % small batches; otherwise a one-case batch always goes
                    % to fold 1 of every permutation.
                    sourceFold = mod(f + nExisting + p - 2, nFold) + 1;
                    newTrain = nExisting + double(newOuter.TrainInd{p,sourceFold});
                    newTest = nExisting + double(newOuter.TestInd{p,sourceFold});
                    cv.TrainInd{p,f} = [oldTrain(:); uint16(newTrain(:))];
                    oldTest = cv.TestInd{p,f};
                    cv.TestInd{p,f} = [oldTest(:); uint16(newTest(:))];

                    if isempty(newTrain), continue; end
                    inner = cv.cvin{p,f};
                    [nInnerPerm,nInnerFold] = size(inner.TrainInd);
                    assert(nInnerPerm == RAND.InnerPerm && nInnerFold == RAND.InnerFold, ...
                        'NMCVPartitionTools:subjectShape','Existing CV1 folds differ from RAND.');
                    assert(isequal(size(inner.TestInd),[nInnerPerm nInnerFold]), ...
                        'NMCVPartitionTools:subjectShape','Existing CV1 train/test dimensions differ.');
                    innerLabels = label(newTrain);
                    if ~classStratified
                        innerLabels = ones(size(innerLabels));
                    end
                    newInner = nk_CVpartition(nInnerPerm,nInnerFold,innerLabels,[],[],false, ...
                        'SilenceCVLog',true);
                    for q = 1:nInnerPerm
                        for k = 1:nInnerFold
                            oldITr = inner.TrainInd{q,k};
                            oldITs = inner.TestInd{q,k};
                            sourceInnerFold = mod(k + oldTrainN + q - 2,nInnerFold) + 1;
                            inner.TrainInd{q,k} = [oldITr(:); uint16(oldTrainN + double(newInner.TrainInd{q,sourceInnerFold}))];
                            inner.TestInd{q,k} = [oldITs(:); uint16(oldTrainN + double(newInner.TestInd{q,sourceInnerFold}))];
                        end
                    end
                    cv.cvin{p,f} = inner;
                end
            end
            NM.cv = cv;
            if classStratified
                % Mode 3 refreshes binary class indices/labels without
                % rebuilding the partition assignments made above.
                NM = NMCVPartitionTools.buildCV(NM,3);
            end
        end

        function cv = appendOuterCV(oldcv, newcv, modeflag)
            % appendOuterCV  Append generated outer folds to one scalar legacy CV structure.
            if isempty(oldcv), cv = newcv; return; end
            if ~isstruct(oldcv) || ~isscalar(oldcv) || ~isstruct(newcv) || ~isscalar(newcv)
                error('NMCVPartitionTools:invalidCVShape', ...
                    'CV append requires scalar legacy CV structures.');
            end
            cv = oldcv;
            cv.TrainInd = [cv.TrainInd; newcv.TrainInd];
            cv.TestInd  = [cv.TestInd;  newcv.TestInd];
            cv.cvin     = [cv.cvin;     newcv.cvin];
            if strcmpi(modeflag,'classification')
                if isfield(cv,'class') && isfield(newcv,'class')
                    cv.class = [cv.class; newcv.class];
                end
                if isfield(cv,'classnew') && isfield(newcv,'classnew')
                    cv.classnew = [cv.classnew; newcv.classnew];
                end
            end
        end

        function NM = loadCV(NM, path)
            % loadCV  Load a saved CV structure and its generating settings into NM.
            %
            % Reads the paired cv/RAND payload written by saveCV. The folds and
            % their generating cross-validation settings are restored together so
            % browser/API state reconstructed from NM describes the loaded CV.
            path = char(string(path));
            vars = whos('-file', path);
            names = {vars.name};
            if ~ismember('cv', names)
                error('NMCVPartitionTools:missingCV', ...
                    'The selected file does not contain a CV structure.');
            end
            if ~ismember('RAND', names)
                error('NMCVPartitionTools:missingRAND', ...
                    ['The selected CV file does not contain its cross-validation settings. ' ...
                     'Save the CV structure again with the current NM2 configurator before reusing it.']);
            end
            S = load(path, 'cv', 'RAND');
            if isempty(S.cv)
                error('NMCVPartitionTools:missingCV', ...
                    'The selected file does not contain a CV structure.');
            end
            if ~isstruct(S.RAND) || ~isscalar(S.RAND)
                error('NMCVPartitionTools:missingRAND', ...
                    ['The selected CV file does not contain its cross-validation settings. ' ...
                     'Save the CV structure again with the current NM2 configurator before reusing it.']);
            end
            if ~isfield(NM,'TrainParam') || ~isstruct(NM.TrainParam), NM.TrainParam = struct(); end
            NM.cv = S.cv;
            NM.TrainParam.RAND = S.RAND;
        end

        function saveCV(NM, path)
            % saveCV  Persist the current CV structure and its generating settings.
            %
            % Writes NM.cv together with NM.TrainParam.RAND so loading the file
            % restores both the predefined partitions and the configurator state
            % that generated them. No folds are rebuilt during save.
            if ~isfield(NM,'cv') || isempty(NM.cv)
                error('NMCVPartitionTools:noCV', 'No NM.cv structure is available for saving.');
            end
            if ~isfield(NM,'TrainParam') || ~isstruct(NM.TrainParam) || ...
                    ~isfield(NM.TrainParam,'RAND') || ~isstruct(NM.TrainParam.RAND) || ...
                    ~isscalar(NM.TrainParam.RAND)
                error('NMCVPartitionTools:noRAND', ...
                    'No cross-validation settings are available for saving with NM.cv.');
            end
            path = char(string(path));
            if isempty(fileparts(path))
                [~,nm,ext] = fileparts(path);
                if isempty(ext), ext = '.mat'; end
                if ~startsWith(nm, 'CVstruct_'), nm = ['CVstruct_' nm]; end
                path = fullfile(pwd, [nm ext]);
            else
                [pn,nm,ext] = fileparts(path);
                if isempty(ext), ext = '.mat'; end
                path = fullfile(pn, [nm ext]);
            end
            cv = NM.cv; %#ok<NASGU>
            RAND = NM.TrainParam.RAND; %#ok<NASGU>
            save(path, 'cv', 'RAND');
        end

        function writePlotContext(NM, path)
            % writePlotContext  Serialize the minimal context needed for CV equalization plots.
            %
            % Writes NM-derived label/covariate data and CV state to a temporary file that plotting helpers can read without touching the full workspace. This keeps browser plot callbacks deterministic and lightweight.
            NMcvctx = struct(); %#ok<NASGU>
            NMcvctx.modeflag = NMAlternativeLabelTools.effectiveMode(NM);
            NMcvctx.label = NMAlternativeLabelTools.activeLabel(NM);
            if isfield(NM,'covars'), NMcvctx.covars = NM.covars; end
            if isfield(NM,'covnames'), NMcvctx.covnames = NM.covnames; end
            if isfield(NM,'cv'), NMcvctx.cv = NM.cv; end
            NMcvctx.TrainParam = struct();
            if isfield(NM,'TrainParam') && isstruct(NM.TrainParam) && ...
                    isfield(NM.TrainParam,'RAND') && isstruct(NM.TrainParam.RAND)
                NMcvctx.TrainParam.RAND = NM.TrainParam.RAND;
            else
                NMcvctx.TrainParam.RAND = NMCVPartitionTools.defaultRAND(NM);
            end
            save(char(string(path)), 'NMcvctx');
        end

        function out = plotRegressionHistogramFromState(contextPath, state, equalized)
            % plotRegressionHistogramFromState  Plot regression-label histograms from serialized CV state.
            %
            % Loads the context created by writePlotContext and renders equalized or raw regression target distributions for browser/runtime preview. The method reads only the context file and returns plot metadata when available.
            S = load(char(string(contextPath)), 'NMcvctx');
            NM = S.NMcvctx;
            if exist('NMConfigTools','class') == 8
                state = NMConfigTools.charifyStrings(state);
            end
            if nargin < 3 || isempty(equalized), equalized = false; end
            RAND = NMCVPartitionTools.completeRAND(NM, NM.TrainParam.RAND);
            RAND = NMCVPartitionTools.applyEq(NM, RAND, state);
            NM.TrainParam.RAND = RAND;
            NMCVPartitionTools.plotRegressionHistogram(NM, logical(equalized));
            if logical(equalized)
                msg = 'Equalized CV1 histogram opened in MATLAB.';
            else
                msg = 'Original regression-label histogram opened in MATLAB.';
            end
            out = struct('ok', true, 'message', msg);
        end

        function plotRegressionHistogram(NM, equalized)
            % plotRegressionHistogram  Render a regression target histogram directly from NM.
            %
            % Builds the plot context from the current workspace and displays the equalized or raw distribution using MATLAB plotting. This is a diagnostic visualization path; it does not alter CV partitions.
            if ~strcmp(NMAlternativeLabelTools.effectiveMode(NM), 'regression')
                error('NMCVPartitionTools:notRegression', 'Histogram display is only defined for regression labels.');
            end
            Eq = NM.TrainParam.RAND.Eq;
            y = Eq.Covar;
            ttl = ['Histogram analysis of ' char(string(Eq.CovarName))];
            if equalized
                cv = NM.cv;
                if iscell(cv), cv = cv{1}; end
                y = y(cv.TrainInd{1,1}(cv.cvin{1,1}.TrainInd{1,1}));
                ttl = ['Analysis of equalized histogram of ' char(string(Eq.CovarName))];
            end
            figure;
            histogram(y, Eq.bincount);
            ylabel('# of observations in bins');
            xlabel(char(string(Eq.CovarName)));
            title(ttl);
        end
    end

    methods (Static, Access = private)

        function state = cliNormalizeFriendlyValues(state)
            c = NMCVPartitionTools.apiChoices();
            state = NMConfigureAPITools.normalizeChoices(state, rmfield(c, {'cvOuterMode','cvInnerMode'}), 'MATLAB:assertion:failed');
            if isfield(state,'cvConstrainedGroupIndex') && ~isempty(state.cvConstrainedGroupIndex)
                state.cvConstrainedCV = 1;
            end
            if isfield(state,'cvOnlyGroupIndex') && ~isempty(state.cvOnlyGroupIndex)
                state.cvOnlyGroupFlag = 1;
            end
        end

        function RAND = defaultRAND(NM) %#ok<INUSD>
            RAND = struct();
            RAND.CV2Frame = 1;
            RAND.OuterFold = 10;
            RAND.OuterPerm = 1;
            RAND.InnerFold = 10;
            RAND.InnerPerm = 1;
            RAND.Decompose = 1;
            RAND.Eq = struct('enabled', false, 'bincount', 10, 'mincount', 10, 'maxcount', 10, ...
                'addremoved2test', 1, 'Covar', [], 'CovarName', 'NM.label', 'posnegrat', 1.5);
            RAND.ConstrainedCV = 2;
            RAND.ConstrainedGroupIndex = [];
            RAND.CVOnlyGroup = struct('flag', 2, 'index', [], 'level', 1);
        end

        function RAND = completeRAND(NM, RAND)
            D = NMCVPartitionTools.defaultRAND(NM);
            RAND = NMCVPartitionTools.mergeStruct(D, RAND);
            if isempty(RAND.Eq.Covar)
                RAND.Eq.Covar = NMCVPartitionTools.labelCovar(NM);
                RAND.Eq.CovarName = 'NM.label';
            end
            [isMulticlass, ~, ~] = NMAlternativeLabelTools.effectiveClassInfo(NM);
            if ~isMulticlass, RAND.Decompose = 1; end
        end

        function state = normalizeState(NM, state)
            if ~isfield(state,'cvFramework'), state.cvFramework = 1; end
            assert(ismember(state.cvFramework,1:4), 'Invalid CV framework code. Allowed: 1, 2, 3, 4.');
            if ~isfield(state,'cvOuterMode') || isempty(state.cvOuterMode), state.cvOuterMode = 'kfold'; end
            if ~isfield(state,'cvInnerMode') || isempty(state.cvInnerMode), state.cvInnerMode = 'kfold'; end
            cvModes = {NMCVPartitionTools.ModeChoices.symbol};
            assert(any(strcmpi(state.cvOuterMode,cvModes)), 'Invalid CV2Mode: allowed kfold, loo, group.');
            assert(any(strcmpi(state.cvInnerMode,cvModes)), 'Invalid CV1Mode: allowed kfold, loo, group.');
            if state.cvFramework ~= 1, state.cvOuterMode = 'group'; end
            if any(state.cvFramework == [3 4]), state.cvInnerMode = 'group'; end
            if ~isfield(state,'cvOuterFold'), state.cvOuterFold = 10; end
            if ~isfield(state,'cvInnerFold'), state.cvInnerFold = 10; end
            if ~isfield(state,'cvOuterPerm'), state.cvOuterPerm = 1; end
            if ~isfield(state,'cvInnerPerm'), state.cvInnerPerm = 1; end
            state.cvOuterFold = round(double(state.cvOuterFold));
            state.cvInnerFold = round(double(state.cvInnerFold));
            state.cvOuterPerm = max(1, round(double(state.cvOuterPerm)));
            state.cvInnerPerm = max(1, round(double(state.cvInnerPerm)));
            if strcmpi(state.cvOuterMode,'loo'), state.cvOuterFold = -1; state.cvOuterPerm = 1; end
            if strcmpi(state.cvInnerMode,'loo'), state.cvInnerFold = -1; state.cvInnerPerm = 1; end
            if state.cvFramework == 3, state.cvOuterPerm = 1; state.cvInnerPerm = 1; end
            if state.cvFramework == 4, state.cvOuterPerm = 1; state.cvInnerPerm = 1; end
            if ~isfield(state,'cvDecompose'), state.cvDecompose = 1; end
            [isMulticlass, ~, ~] = NMAlternativeLabelTools.effectiveClassInfo(NM);
            if isMulticlass
                if strcmpi(state.cvOuterMode,'loo') || strcmpi(state.cvInnerMode,'loo')
                    state.cvDecompose = 2;
                else
                    assert(ismember(state.cvDecompose,[1 2 9]), 'Invalid decomposition code. Allowed: 1, 2, 9.');
                end
            else
                state.cvDecompose = 1;
            end
        end

        function RAND = RANDFromState(NM, state)
            RAND = NMCVPartitionTools.completeRAND(NM, NM.TrainParam.RAND);
            RAND.CV2Frame = state.cvFramework;
            switch state.cvFramework
                case 1
                    if isfield(RAND,'CV2LCO'), RAND = rmfield(RAND,'CV2LCO'); end
                    if isfield(RAND,'CV1LCO'), RAND = rmfield(RAND,'CV1LCO'); end
                    RAND.OuterFold = state.cvOuterFold;
                    RAND.OuterPerm = state.cvOuterPerm;
                    RAND.InnerFold = state.cvInnerFold;
                    RAND.InnerPerm = state.cvInnerPerm;
                case 2
                    if isfield(RAND,'CV1LCO'), RAND = rmfield(RAND,'CV1LCO'); end
                    ind = NMCVPartitionTools.resolveIndex(NM, state, 'cvOuterGroupSourceVar', 'cvOuterGroupIndex');
                    RAND.CV2LCO.ind = ind;
                    RAND.OuterFold = numel(unique(ind));
                    RAND.OuterPerm = state.cvOuterPerm;
                    RAND.InnerFold = state.cvInnerFold;
                    RAND.InnerPerm = state.cvInnerPerm;
                case {3,4}
                    ind2 = NMCVPartitionTools.resolveIndex(NM, state, 'cvOuterGroupSourceVar', 'cvOuterGroupIndex');
                    ind1 = NMCVPartitionTools.resolveIndex(NM, state, 'cvInnerGroupSourceVar', 'cvInnerGroupIndex');
                    RAND.CV2LCO.ind = ind2;
                    RAND.CV1LCO.ind = ind1;
                    RAND.OuterFold = numel(unique(ind2));
                    RAND.InnerFold = numel(unique(ind1));
                    RAND.OuterPerm = 1;
                    RAND.InnerPerm = 1;
            end
            RAND.Decompose = state.cvDecompose;
            RAND = NMCVPartitionTools.applyEq(NM, RAND, state);
            RAND = NMCVPartitionTools.applyConstrained(NM, RAND, state);
            RAND = NMCVPartitionTools.applyCVOnly(NM, RAND, state);
        end

        function RAND = applyEq(NM, RAND, state)
            if ~isfield(RAND,'Eq') || ~isstruct(RAND.Eq), RAND.Eq = NMCVPartitionTools.defaultRAND(NM).Eq; end
            RAND.Eq.enabled = isfield(state,'cvEqEnabled') && logical(state.cvEqEnabled);
            if ~isfield(state,'cvEqAddRemoved2Test'), state.cvEqAddRemoved2Test = 1; end
            RAND.Eq.addremoved2test = double(logical(state.cvEqAddRemoved2Test));
            if strcmp(NMAlternativeLabelTools.effectiveMode(NM),'regression')
                RAND.Eq.mincount = NMCVPartitionTools.getNumber(state,'cvEqMinCount',10);
                RAND.Eq.maxcount = NMCVPartitionTools.getNumber(state,'cvEqMaxCount',10);
                RAND.Eq.bincount = NMCVPartitionTools.getNumber(state,'cvEqBinCount',10);
                if isfield(state,'cvEqTarget') && strcmpi(char(string(state.cvEqTarget)),'covariate') && ...
                        (state.cvEqCovariateIndex > 0 || ~strcmp(state.cvEqCovarName,'NM.label'))
                    if state.cvEqCovariateIndex > 0
                        ci = round(double(state.cvEqCovariateIndex));
                    else
                        name = state.cvEqCovarName;
                        ci = find(strcmp(NM.covnames,name));
                        assert(isscalar(ci),'NMCVPartitionTools:eqCovariate', ...
                            'Equalization covariate %s must occur exactly once.',name);
                    end
                    RAND.Eq.Covar = NM.covars(:,ci);
                    if isfield(NM,'covnames') && numel(NM.covnames) >= ci, RAND.Eq.CovarName = NM.covnames{ci}; else, RAND.Eq.CovarName = sprintf('covariate_%d',ci); end
                else
                    RAND.Eq.Covar = NMCVPartitionTools.labelCovar(NM);
                    RAND.Eq.CovarName = 'NM.label';
                end
            else
                RAND.Eq.posnegrat = NMCVPartitionTools.getNumber(state,'cvEqPosNegRatio',1.5);
            end
        end

        function RAND = applyConstrained(NM, RAND, state)
            allow = state.cvFramework == 1 && ~strcmpi(state.cvOuterMode,'loo') && ~strcmpi(state.cvInnerMode,'loo');
            if allow && isfield(state,'cvConstrainedCV') && round(double(state.cvConstrainedCV)) == 1
                RAND.ConstrainedCV = 1;
                RAND.ConstrainedGroupIndex = NMCVPartitionTools.resolveIndex(NM, state, 'cvConstrainedSourceVar', 'cvConstrainedGroupIndex');
            else
                RAND.ConstrainedCV = 2;
            end
        end

        function RAND = applyCVOnly(NM, RAND, state)
            if ~isfield(RAND,'CVOnlyGroup') || ~isstruct(RAND.CVOnlyGroup)
                RAND.CVOnlyGroup = struct('flag',2,'index',[],'level',1);
            end
            if isfield(state,'cvOnlyGroupFlag') && round(double(state.cvOnlyGroupFlag)) == 1
                RAND.CVOnlyGroup.flag = 1;
                RAND.CVOnlyGroup.index = NMCVPartitionTools.resolveIndex(NM, state, 'cvOnlyGroupSourceVar', 'cvOnlyGroupIndex');
                RAND.CVOnlyGroup.level = 1;
            else
                RAND.CVOnlyGroup.flag = 2;
            end
        end

        function ind = resolveIndex(NM, state, sourceField, valueField)
            ind = [];
            if isfield(state,sourceField) && ~isempty(state.(sourceField))
                ind = NMWorkspaceTools.resolve(char(string(state.(sourceField))), 'base');
            elseif isfield(state,valueField)
                ind = state.(valueField);
            end
            if isempty(ind)
                error('NMCVPartitionTools:missingIndex', 'Select a workspace vector for %s.', sourceField);
            end
            ind = ind(:);
            n = NMCVPartitionTools.nSamples(NM);
            if numel(ind) ~= n
                error('NMCVPartitionTools:indexSize', 'CV index vector must have %d rows.', n);
            end
        end

        function fields = flatCVFields(state)
            fields = struct();
            if ~isstruct(state), return; end
            f = fieldnames(state);
            for i = 1:numel(f)
                if startsWith(f{i}, 'cv')
                    fields.(f{i}) = state.(f{i});
                end
            end
        end

        function tf = canAppend(NM, RAND)
            tf = false;
            if ~isfield(NM,'cv') || isempty(NM.cv) || ~isstruct(NM.cv) || ~isscalar(NM.cv), return; end
            try
                tf = RAND.OuterFold == size(NM.cv(1).TrainInd,2) && ...
                     RAND.InnerFold == size(NM.cv(1).cvin{1,1}.TrainInd,2);
            catch
                tf = false;
            end
        end

        function mode = outerModeFromRAND(NM, RAND)
            if isfield(RAND,'CV2Frame') && RAND.CV2Frame ~= 1, mode = 'group'; return; end
            if RAND.OuterFold == -1 || RAND.OuterFold == NMCVPartitionTools.nSamples(NM), mode = 'loo'; else, mode = 'kfold'; end
        end

        function mode = innerModeFromRAND(NM, RAND)
            if isfield(RAND,'CV2Frame') && any(RAND.CV2Frame == [3 4]), mode = 'group'; return; end
            n = NMCVPartitionTools.nSamples(NM);
            of = RAND.OuterFold;
            looEquivalent = n;
            if isfinite(of) && of > 1, looEquivalent = n - floor(n/of); end
            if RAND.InnerFold == -1 || RAND.InnerFold == looEquivalent, mode = 'loo'; else, mode = 'kfold'; end
        end

        function y = labelCovar(NM)
            LABEL = NMAlternativeLabelTools.extractLabel(NM);
            if LABEL.flag == 1
                y = NMAlternativeLabelTools.activeLabel(NM);
            elseif isfield(NM,'TrainParam') && isfield(NM.TrainParam,'MULTILABEL') && isfield(NM.TrainParam.MULTILABEL,'sel')
                y = nm_nanmean(NM.label(:,NM.TrainParam.MULTILABEL.sel),2);
            else
                y = nm_nanmean(NM.label,2);
            end
        end

        function n = nSamples(NM)
            if isfield(NM,'cases') && ~isempty(NM.cases), n = numel(NM.cases);
            elseif isfield(NM,'n_subjects_all') && ~isempty(NM.n_subjects_all), n = double(NM.n_subjects_all);
            else, n = size(NM.label,1); end
        end

        function names = covariateNames(NM)
            if isfield(NM,'covnames') && ~isempty(NM.covnames), names = cellstr(string(NM.covnames)); else, names = {}; end
        end

        function s = indexSummary(ind)
            if isempty(ind), s = 'undefined'; return; end
            if islogical(ind), s = sprintf('%d selected cases among %d', sum(ind(:)), numel(ind));
            else, s = sprintf('%d groups among %d cases', numel(unique(ind(:))), numel(ind)); end
        end

        function val = getField(s, f, d)
            if isstruct(s) && isfield(s,f) && ~isempty(s.(f)), val = s.(f); else, val = d; end
        end

        function val = getNumber(s, f, d)
            if isstruct(s) && isfield(s,f) && ~isempty(s.(f)), val = double(s.(f)); else, val = d; end
            if isempty(val) || ~isfinite(val(1)), val = d; else, val = val(1); end
        end

        function S = mergeStruct(A, B)
            S = A;
            if ~isstruct(B), return; end
            f = fieldnames(B);
            for i = 1:numel(f), S.(f{i}) = B.(f{i}); end
        end
    end
end
